package com.bank.capacity.service;

// Immutable result of a capacity calculation (Builder pattern for readability).
public class CapacityPlan {
    private final double concurrency;
    private final long transientBytes;
    private final long recommendedHeapBytes;
    private final double allocationRateGBps;

    private CapacityPlan(Builder b) {
        this.concurrency = b.concurrency;
        this.transientBytes = b.transientBytes;
        this.recommendedHeapBytes = b.recommendedHeapBytes;
        this.allocationRateGBps = b.allocationRateGBps;
    }
    public double getConcurrency() { return concurrency; }
    public long getTransientBytes() { return transientBytes; }
    public long getRecommendedHeapBytes() { return recommendedHeapBytes; }
    public double getAllocationRateGBps() { return allocationRateGBps; }

    public static Builder builder() { return new Builder(); }

    public static class Builder {
        private double concurrency;
        private long transientBytes;
        private long recommendedHeapBytes;
        private double allocationRateGBps;
        public Builder concurrency(double v) { this.concurrency = v; return this; }
        public Builder transientBytes(long v) { this.transientBytes = v; return this; }
        public Builder recommendedHeapBytes(long v) { this.recommendedHeapBytes = v; return this; }
        public Builder allocationRateGBps(double v) { this.allocationRateGBps = v; return this; }
        public CapacityPlan build() { return new CapacityPlan(this); }
    }
}
