package com.bank.capacity.service;

import java.util.logging.Logger;

// Turns throughput + latency targets into concurrency, memory, and heap sizing.
public class CapacityPlanner {
    private static final Logger log = Logger.getLogger(CapacityPlanner.class.getName());
    private static final long STEADY_STATE_BYTES = 300L * 1024 * 1024;   // caches, pools
    private static final double HEAP_MULTIPLIER = 3.0;                   // heap ≈ 3× live set

    // Little's Law: L = λ × W  (concurrency = tps × latencySeconds).
    public double concurrency(double tps, double latencyMs) {
        if (tps <= 0 || latencyMs <= 0) throw new IllegalArgumentException("tps and latencyMs must be > 0");
        double c = tps * (latencyMs / 1000.0);
        log.info(() -> "Little's Law: " + tps + " TPS × " + latencyMs + "ms = " + c + " concurrent");
        return c;
    }

    public CapacityPlan plan(double tps, double latencyMs,
                             long perRequestRetainedBytes, double perRequestAllocMB) {
        double concurrency = concurrency(tps, latencyMs);
        long transientBytes = (long) concurrency * perRequestRetainedBytes;
        long liveSet = transientBytes + STEADY_STATE_BYTES;
        long recommendedHeap = (long) (liveSet * HEAP_MULTIPLIER);
        double allocationRateGBps = (tps * perRequestAllocMB) / 1024.0;

        log.info(() -> "Transient working set: " + (transientBytes / (1024 * 1024)) + " MB");
        log.info(() -> "Recommended heap: " + (recommendedHeap / (1024 * 1024)) + " MB");
        log.info(() -> "Allocation rate: " + String.format("%.2f", allocationRateGBps) + " GB/s");

        return CapacityPlan.builder()
                .concurrency(concurrency)
                .transientBytes(transientBytes)
                .recommendedHeapBytes(recommendedHeap)
                .allocationRateGBps(allocationRateGBps)
                .build();
    }
}
