package com.bank.capacity.service;

import java.util.logging.Logger;

// Runnable demo: plan for 1000 TPS at 100ms, 2MB retained, 4MB allocated per request.
public class CapacityPlanningApplication {
    private static final Logger log = Logger.getLogger(CapacityPlanningApplication.class.getName());

    public static void main(String[] args) {
        CapacityPlanner planner = new CapacityPlanner();

        long twoMB = 2L * 1024 * 1024;
        CapacityPlan plan = planner.plan(1000, 100, twoMB, 4.0);

        log.info(() -> "=== Payments API capacity plan ===");
        log.info(() -> "Concurrent requests: " + plan.getConcurrency());
        log.info(() -> "Transient set (MB): " + (plan.getTransientBytes() / (1024 * 1024)));
        log.info(() -> "Recommended -Xmx (MB): " + (plan.getRecommendedHeapBytes() / (1024 * 1024)));
        log.info(() -> "Allocation rate (GB/s): " + String.format("%.2f", plan.getAllocationRateGBps()));
        log.info(() -> "Suggested GC: G1GC with -XX:MaxGCPauseMillis=50 (within 100ms budget)");
    }
}
