package com.bank.capacity.service;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.assertThat;
import static org.junit.jupiter.api.Assertions.assertThrows;

class CapacityPlannerTest {

    private final CapacityPlanner planner = new CapacityPlanner();

    @Test
    void littlesLaw_1000tps_100ms_gives100Concurrent() {
        assertThat(planner.concurrency(1000, 100)).isEqualTo(100.0);
    }

    @Test
    void littlesLaw_scalesWithLatency() {
        // Double the latency → double the concurrency for the same TPS.
        assertThat(planner.concurrency(1000, 200)).isEqualTo(200.0);
    }

    @Test
    void transientSet_isConcurrencyTimesPerRequest() {
        long twoMB = 2L * 1024 * 1024;
        CapacityPlan plan = planner.plan(1000, 100, twoMB, 4.0);
        // 100 concurrent × 2MB = 200MB transient
        assertThat(plan.getTransientBytes()).isEqualTo(100L * twoMB);
    }

    @Test
    void biggerPerRequest_meansBiggerHeap() {
        long twoMB = 2L * 1024 * 1024;
        long fourMB = 4L * 1024 * 1024;
        long heapSmall = planner.plan(1000, 100, twoMB, 4.0).getRecommendedHeapBytes();
        long heapBig = planner.plan(1000, 100, fourMB, 4.0).getRecommendedHeapBytes();
        assertThat(heapBig).isGreaterThan(heapSmall);
    }

    @Test
    void allocationRate_1000tps_4mb_isAboutFourGBps() {
        CapacityPlan plan = planner.plan(1000, 100, 2L * 1024 * 1024, 4.0);
        // 1000 × 4MB = 4000MB/s ≈ 3.9 GB/s
        assertThat(plan.getAllocationRateGBps()).isBetween(3.8, 4.0);
    }

    @Test
    void zeroTps_isRejected() {
        assertThrows(IllegalArgumentException.class, () -> planner.concurrency(0, 100));
    }
}
